import moment from 'moment-jalaali';

// Configure moment-jalaali
moment.loadPersian({
  dialect: 'persian-modern',
  usePersianDigits: true
});

export const persianDate = {
  // Get current Persian date
  getCurrentDate() {
    return moment().format('jYYYY/jMM/jDD');
  },

  // Get current Persian datetime
  getCurrentDateTime() {
    return moment().format('jYYYY/jMM/jDD - HH:mm');
  },

  // Convert Gregorian to Persian
  toPersian(date) {
    return moment(date).format('jYYYY/jMM/jDD');
  },

  // Convert Persian to Gregorian
  toGregorian(persianDate) {
    return moment(persianDate, 'jYYYY/jMM/jDD').format('YYYY-MM-DD');
  },

  // Get Persian day name
  getDayName(date = null) {
    const targetDate = date ? moment(date) : moment();
    return targetDate.format('dddd');
  },

  // Get Persian month name
  getMonthName(date = null) {
    const targetDate = date ? moment(date) : moment();
    return targetDate.format('jMMMM');
  },

  // Add days to Persian date
  addDays(days, date = null) {
    const targetDate = date ? moment(date) : moment();
    return targetDate.add(days, 'days').format('jYYYY/jMM/jDD');
  },

  // Get date range (for yesterday, today, tomorrow)
  getDateRange() {
    const today = moment();
    const yesterday = moment().subtract(1, 'days');
    const tomorrow = moment().add(1, 'days');

    return {
      yesterday: {
        gregorian: yesterday.format('YYYY-MM-DD'),
        persian: yesterday.format('jYYYY/jMM/jDD'),
        dayName: yesterday.format('dddd')
      },
      today: {
        gregorian: today.format('YYYY-MM-DD'),
        persian: today.format('jYYYY/jMM/jDD'),
        dayName: today.format('dddd')
      },
      tomorrow: {
        gregorian: tomorrow.format('YYYY-MM-DD'),
        persian: tomorrow.format('jYYYY/jMM/jDD'),
        dayName: tomorrow.format('dddd')
      }
    };
  },

  // Format time in Persian style
  formatTime(time) {
    return moment(time, 'HH:mm').format('HH:mm');
  },

  // Get Persian calendar for a month
  getMonthCalendar(year, month) {
    const startDate = moment(`${year}/${month}/1`, 'jYYYY/jMM/jDD');
    const daysInMonth = startDate.jDaysInMonth();
    const calendar = [];

    for (let day = 1; day <= daysInMonth; day++) {
      const currentDate = moment(`${year}/${month}/${day}`, 'jYYYY/jMM/jDD');
      calendar.push({
        day,
        date: currentDate.format('jYYYY/jMM/jDD'),
        gregorian: currentDate.format('YYYY-MM-DD'),
        dayName: currentDate.format('dddd'),
        isToday: currentDate.isSame(moment(), 'day')
      });
    }

    return calendar;
  }
};

export default persianDate;
